// CheapestStation is the resolver for the cheapestStation field.
func (r *departmentStatsResolver) CheapestStation(ctx context.Context, obj *model.DepartmentStats) (*model.Station, error) {
	ids, err := r.Stations.IDsByDepartment(ctx, obj.Department)
	if err != nil {
		return nil, err
	}
	// Un seul MGET pour toutes les stations du département
	current, err := r.Current.GetMany(ctx, ids)
	if err != nil {
		return nil, err
	}
	bestID, bestPrice := "", 0.0
	for id, list := range current {
		p, ok := priceOf(list, string(obj.Fuel))
		// À prix égal on prend le plus petit identifiant, pour un résultat stable
		if ok && (bestID == "" || p < bestPrice || (p == bestPrice && id < bestID)) {
			bestID, bestPrice = id, p
		}
	}
	if bestID == "" {
		return nil, nil
	}
	found, err := r.Stations.ByIDs(ctx, []string{bestID})
	if err != nil {
		return nil, err
	}
	doc, ok := found[bestID]
	if !ok {
		return nil, nil
	}
	return model.StationFromDoc(doc), nil
}

